// among a segment's members (their customer ids passed in - the commerce half,
// customer_segment_memberships, lives in the commerce db). Distinct-member counts,
// resolved across customer_id + stitched anon ids. Channel- and time-bounded (the
// CROSS JOIN LATERAL jsonb-expands every row it touches).
func (q *Queries) SegmentAffinitiesForMembers(ctx context.Context, arg SegmentAffinitiesForMembersParams) ([]SegmentAffinitiesForMembersRow, error) {
	rows, err := q.db.QueryContext(ctx, segmentAffinitiesForMembers,
		arg.ChannelID,
		arg.Since,
		pq.Array(arg.MemberIds),
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SegmentAffinitiesForMembersRow{}
	for rows.Next() {
		var i SegmentAffinitiesForMembersRow
		if err := rows.Scan(&i.AttrKey, &i.AttrVal, &i.Members); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const segmentAffinitiesForMembersSmall = `-- name: SegmentAffinitiesForMembersSmall :many
SELECT kv.k AS attr_key, kv.v AS attr_val, COUNT(DISTINCT COALESCE(e.customer_id, i.customer_id))::int AS members
FROM analytics_events e
LEFT JOIN analytics_identities i ON i.anon_id = e.anon_id
CROSS JOIN LATERAL jsonb_each_text(CASE WHEN jsonb_typeof(e.properties) = 'object' THEN e.properties ELSE '{}'::jsonb END) AS kv(k, v)
WHERE e.channel_id = $1
  AND e.occurred_at >= $2
  AND NOT COALESCE((e.properties->>'is_bot')::boolean, FALSE)
  AND (e.customer_id = ANY($3::uuid[]) OR e.anon_id = ANY($4::text[]))
  AND COALESCE(e.customer_id, i.customer_id) = ANY($3::uuid[])
  AND kv.k LIKE 'attr:%' AND kv.v <> ''
GROUP BY kv.k, kv.v
ORDER BY members DESC, kv.k
LIMIT $5
`

type SegmentAffinitiesForMembersSmallParams struct {
	ChannelID     uuid.NullUUID `json:"channel_id"`
	Since         time.Time     `json:"since"`
	MemberIds     []uuid.UUID   `json:"member_ids"`
	MemberAnonIds []string      `json:"member_anon_ids"`
	Lim           int32         `json:"lim"`
}

type SegmentAffinitiesForMembersSmallRow struct {
	AttrKey interface{} `json:"attr_key"`
	AttrVal interface{} `json:"attr_val"`
	Members int32       `json:"members"`
}

// Index-friendly variant for ordinary segment sizes: the OR arms hit the partial
// customer/anon time indexes (BitmapOr) where the bare COALESCE above can only
// scan the channel window. The COALESCE condition stays as the exact filter -
// the anon arm alone would admit events whose customer_id is a non-member. The
// caller resolves the members' anon ids first and picks this variant when the
// arrays are small enough to probe.
func (q *Queries) SegmentAffinitiesForMembersSmall(ctx context.Context, arg SegmentAffinitiesForMembersSmallParams) ([]SegmentAffinitiesForMembersSmallRow, error) {
	rows, err := q.db.QueryContext(ctx, segmentAffinitiesForMembersSmall,
		arg.ChannelID,
		arg.Since,
		pq.Array(arg.MemberIds),
		pq.Array(arg.MemberAnonIds),
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SegmentAffinitiesForMembersSmallRow{}
	for rows.Next() {
		var i SegmentAffinitiesForMembersSmallRow
		if err := rows.Scan(&i.AttrKey, &i.AttrVal, &i.Members); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const segmentEventActors = `-- name: SegmentEventActors :many
SELECT COALESCE(e.customer_id, i.customer_id)::uuid AS customer_id
FROM analytics_events e
LEFT JOIN analytics_identities i ON i.anon_id = e.anon_id
WHERE e.channel_id = $1
  AND e.event_name = $2
  AND e.occurred_at >= $3
  AND NOT COALESCE((e.properties->>'is_bot')::boolean, FALSE)
  AND COALESCE(e.customer_id, i.customer_id) IS NOT NULL
GROUP BY 1
HAVING COUNT(*) >= $4::bigint
`

type SegmentEventActorsParams struct {
	ChannelID uuid.NullUUID `json:"channel_id"`
	EventName string        `json:"event_name"`
	Since     time.Time     `json:"since"`
	MinCount  int64         `json:"min_count"`
}

// Customers (resolved directly or via a stitched anon) who did a given event at
// least min_count times since the cutoff - one building block of a behavioral
// segment. Anonymous-only people are excluded (segments hold customer ids).
func (q *Queries) SegmentEventActors(ctx context.Context, arg SegmentEventActorsParams) ([]uuid.UUID, error) {
	rows, err := q.db.QueryContext(ctx, segmentEventActors,
		arg.ChannelID,
		arg.EventName,
		arg.Since,
		arg.MinCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var customer_id uuid.UUID
		if err := rows.Scan(&customer_id); err != nil {
			return nil, err
		}
		items = append(items, customer_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const synapseActiveCustomers = `-- name: SynapseActiveCustomers :many
SELECT
    COALESCE(e.customer_id, i.customer_id)::uuid AS customer_id,
    COUNT(*)                                     AS events,
    MAX(e.occurred_at)::timestamptz              AS last_seen
FROM analytics_events e
LEFT JOIN analytics_identities i ON i.anon_id = e.anon_id
WHERE e.channel_id = $1
  AND e.occurred_at >= $2
  AND NOT COALESCE((e.properties->>'is_bot')::boolean, FALSE)
  AND COALESCE(e.customer_id, i.customer_id) IS NOT NULL
GROUP BY 1
ORDER BY events DESC
LIMIT $3
`

